(function(){
'use strict';
const M={
fr:{ey:'ÉTAPE 1 · DOSSIER AVANT TOUT PAIEMENT',pay:'AUCUN PAIEMENT MAINTENANT',payText:'Envoyez d’abord vos renseignements. DIGIYLYFE contrôle votre dossier, prépare votre fiche puis vous la présente. Vous pouvez demander des corrections. Le règlement n’est demandé qu’après votre accord sur la fiche.',send:'ENVOYER MON DOSSIER POUR PRÉPARATION →',ready:'Dossier prêt à être envoyé. Aucun règlement ni preuve de paiement n’est demandé à cette étape.',done:'Dossier reçu. DIGIYLYFE va le contrôler, préparer votre fiche et vous la présenter avant tout règlement.'},
en:{ey:'STEP 1 · FILE BEFORE ANY PAYMENT',pay:'NO PAYMENT NOW',payText:'Send your information first. DIGIYLYFE reviews your file, prepares your professional profile and presents it to you. You can request corrections. Payment is requested only after you approve the profile.',send:'SEND MY FILE FOR PREPARATION →',ready:'Your file is ready to send. No payment or payment proof is required at this stage.',done:'File received. DIGIYLYFE will review it, prepare your profile and present it to you before any payment.'},
es:{ey:'PASO 1 · EXPEDIENTE ANTES DE CUALQUIER PAGO',pay:'NINGÚN PAGO AHORA',payText:'Envíe primero sus datos. DIGIYLYFE revisa su expediente, prepara su ficha y se la presenta. Puede solicitar correcciones. El pago solo se solicita después de su aprobación.',send:'ENVIAR MI EXPEDIENTE PARA PREPARACIÓN →',ready:'Expediente listo. No se solicita pago ni comprobante en esta etapa.',done:'Expediente recibido. DIGIYLYFE lo revisará, preparará su ficha y se la presentará antes de cualquier pago.'},
pt:{ey:'ETAPA 1 · DOSSIER ANTES DE QUALQUER PAGAMENTO',pay:'NENHUM PAGAMENTO AGORA',payText:'Envie primeiro os seus dados. A DIGIYLYFE analisa o dossier, prepara a ficha e apresenta-a. Pode pedir correções. O pagamento só é pedido após a sua aprovação.',send:'ENVIAR O MEU DOSSIER PARA PREPARAÇÃO →',ready:'Dossier pronto. Nenhum pagamento ou comprovativo é exigido nesta etapa.',done:'Dossier recebido. A DIGIYLYFE irá analisá-lo, preparar a ficha e apresentá-la antes de qualquer pagamento.'},
it:{ey:'FASE 1 · DOSSIER PRIMA DI QUALSIASI PAGAMENTO',pay:'NESSUN PAGAMENTO ORA',payText:'Invia prima i tuoi dati. DIGIYLYFE controlla il dossier, prepara la scheda e te la presenta. Puoi chiedere correzioni. Il pagamento viene richiesto solo dopo la tua approvazione.',send:'INVIA IL DOSSIER PER LA PREPARAZIONE →',ready:'Dossier pronto. In questa fase non è richiesto alcun pagamento o prova di pagamento.',done:'Dossier ricevuto. DIGIYLYFE lo controllerà, preparerà la scheda e te la presenterà prima di qualsiasi pagamento.'},
de:{ey:'SCHRITT 1 · UNTERLAGEN VOR JEDER ZAHLUNG',pay:'JETZT KEINE ZAHLUNG',payText:'Senden Sie zuerst Ihre Angaben. DIGIYLYFE prüft Ihre Unterlagen, erstellt Ihr Profi-Profil und legt es Ihnen vor. Korrekturen sind möglich. Die Zahlung erfolgt erst nach Ihrer Freigabe.',send:'UNTERLAGEN ZUR ERSTELLUNG SENDEN →',ready:'Unterlagen bereit. In diesem Schritt sind weder Zahlung noch Zahlungsnachweis erforderlich.',done:'Unterlagen erhalten. DIGIYLYFE prüft sie, erstellt das Profil und legt es Ihnen vor jeder Zahlung vor.'},
nl:{ey:'STAP 1 · DOSSIER VÓÓR ENIGE BETALING',pay:'NU GEEN BETALING',payText:'Stuur eerst uw gegevens. DIGIYLYFE controleert het dossier, maakt het professionele profiel en legt het aan u voor. U kunt correcties vragen. Betaling wordt pas na uw goedkeuring gevraagd.',send:'MIJN DOSSIER VOOR VOORBEREIDING VERSTUREN →',ready:'Dossier klaar. In deze stap is geen betaling of betalingsbewijs nodig.',done:'Dossier ontvangen. DIGIYLYFE controleert het, maakt het profiel en legt het vóór enige betaling aan u voor.'},
ar:{ey:'الخطوة 1 · الملف قبل أي دفع',pay:'لا دفع الآن',payText:'أرسل معلوماتك أولاً. تراجع DIGIYLYFE الملف وتُعد ملفك المهني ثم تعرضه عليك. يمكنك طلب التعديلات. لا يُطلب الدفع إلا بعد موافقتك على الملف.',send:'إرسال الملف للإعداد ←',ready:'الملف جاهز للإرسال. لا يُطلب دفع أو إثبات دفع في هذه المرحلة.',done:'تم استلام الملف. ستراجعه DIGIYLYFE وتُعد الملف المهني وتعرضه عليك قبل أي دفع.'}
};
function lang(){const l=(document.documentElement.lang||'fr').slice(0,2).toLowerCase();return M[l]?l:'fr'}
function apply(){const d=M[lang()],ey=document.getElementById('ey'),pt=document.getElementById('proofTitle'),pl=document.getElementById('proofLabel'),ph=document.getElementById('proofHelp'),btn=document.getElementById('submit'),st=document.getElementById('status');if(ey)ey.textContent=d.ey;if(pt)pt.textContent=d.pay;if(pl)pl.textContent=d.payText;if(ph)ph.textContent='';if(btn&&btn.style.display!=='none')btn.textContent=d.send;if(st&&!st.classList.contains('bad')){if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)){if(st.textContent!==d.ready)st.textContent=d.ready}}}
apply();
new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
document.querySelectorAll('#langs button').forEach(b=>b.addEventListener('click',()=>setTimeout(apply,0)));
const st=document.getElementById('status');if(st)new MutationObserver(()=>{const d=M[lang()];if(st.classList.contains('bad'))return;if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)&&st.textContent!==d.ready){st.textContent=d.ready}}).observe(st,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['class']});
})();